// Code node "Read the booking". Pulls the invitee, the event and the booking answers from Calendly.
const FREE = /^(gmail|googlemail|yahoo|hotmail|outlook|live|icloud|me|aol|proton|protonmail|gmx|mail|yandex|zoho)\./i;
const body = $input.first().json;
const p = body.payload || body;
const email = String(p.email || "").trim().toLowerCase();
const domain = email.includes("@") ? email.split("@")[1] : "";
const ev = p.scheduled_event || p.event || {};
const answers = (Array.isArray(p.questions_and_answers) ? p.questions_and_answers : [])
  .map((q) => `${q.question}: ${q.answer}`).join("\n");
return [{
  json: {
    email,
    name: String(p.name || [p.first_name, p.last_name].filter(Boolean).join(" ")).trim(),
    domain,
    work_email: Boolean(domain) && !FREE.test(domain),
    event_name: ev.name || "",
    start_time: ev.start_time || "",
    answers,
  },
}];

// Code node "Slack message". The brief, who booked, when, and what the data cost.
// Shared helper: adds up what the agent's looot calls cost, from the agent's intermediate steps
// (the agent's "Return Intermediate Steps" option is on). Each looot tool answer carries actualCost.
function agentCost(item) {
  const steps = (item && Array.isArray(item.intermediateSteps)) ? item.intermediateSteps : [];
  let usd = 0;
  let calls = 0;
  for (const step of steps) {
    const tool = String((step && step.action && step.action.tool) || "");
    if (!/looot/i.test(tool)) continue;
    calls += 1;
    const text = typeof step.observation === "string" ? step.observation : JSON.stringify(step.observation ?? "");
    for (const m of text.matchAll(/"actualCost"\s*:\s*([0-9.eE+-]+)/g)) {
      const n = Number(m[1]);
      if (Number.isFinite(n)) usd += n;
    }
  }
  return { looot_calls: calls, looot_cost_usd: Number(usd.toFixed(6)) };
}

const item = $input.first().json;
const b = $("Read the booking").first().json;
const cost = agentCost(item);
const brief = typeof item.output === "string" ? item.output : JSON.stringify(item.output ?? "");
const when = b.start_time ? new Date(b.start_time).toUTCString().replace(":00 GMT", " UTC") : "time not given";
return [{
  json: {
    text: `*New booking:* ${b.name || b.email} (${b.email}), ${b.event_name || "meeting"}, ${when}\n\n${brief}\n\n_${cost.looot_calls} looot calls, $${cost.looot_cost_usd.toFixed(4)}_`,
    ...cost,
  },
}];
